
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_lak_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_lak", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.483052703301301e-02, -3.456570223191369e-02, -3.418205820555742e-02, -3.362516445461016e-02, -3.281546627746667e-02, -3.163877061135844e-02, -2.994105441440063e-02, -2.755681225499495e-02, -2.450831793010139e-02, -2.255135665663908e-02, -6.176245422854429e-02, -7.236677143654860e-02, -3.430440738695412e-02, -2.411403916855239e-02, -1.809048661835510e-02, -1.323654137475069e-02, -8.729716304148953e-03, -1.236659128562757e-03, -4.051140938723539e-05, -3.058543523193723e-07]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


